// PROJETO SM3 — CONTENT PLAN QUEUE v1.1
// Fix: existing rows in 04_CONTEUDOS are informational only in this dry-run.
// Eligibility is determined by the CURRENT project curation state.
// This avoids falsely blocking a newly curated project.

const projects = $('READ — CURATED PROJECTS').all().map(i => i.json);
const mediaRows = $('READ — CURATED MEDIA').all().map(i => i.json);
const templates = $('READ — ACTIVE TEMPLATES').all().map(i => i.json);
const contentRows = $input.all().map(i => i.json);

const activeTemplates = templates
  .filter(t => String(t.STATUS || '').trim().toUpperCase() === 'ATIVO')
  .map(t => ({
    template_id: t.ID_TEMPLATE,
    name: t.NOME,
    format: t.FORMATO,
    dimension: t.DIMENSAO || '',
    media_zone: t.ZONA_MIDIA || '',
    text_zone: t.ZONA_TEXTO || '',
    signature: t.ASSINATURA || '',
    crop_rule: t.REGRA_CROP || '',
    text_rule: t.REGRA_TEXTO || ''
  }));

const audit = [];
const out = [];

for (const p of projects) {
  const pid = String(p.ID_PROJETO || '').trim();
  if (!pid) continue;

  const reasons = [];
  const storage = String(p.STORAGE_STATUS || '').trim().toUpperCase();
  const curationStatus = String(p.CURATION_STATUS || '').trim().toUpperCase();
  const curationRun = String(p.CURATION_RUN_ID || '').trim();

  if (storage !== 'ONLINE') reasons.push(`STORAGE_STATUS=${storage || 'EMPTY'}`);
  if (curationStatus !== 'AI_CURATED') reasons.push(`CURATION_STATUS=${curationStatus || 'EMPTY'}`);
  if (!curationRun) reasons.push('CURATION_RUN_ID=EMPTY');

  const curated = mediaRows
    .filter(m =>
      String(m.ID_PROJETO || '').trim() === pid &&
      String(m.STORAGE_STATUS || '').trim().toUpperCase() === 'ONLINE' &&
      String(m.CURATION_STATUS || '').trim().toUpperCase() === 'AI_CURATED' &&
      String(m.CURATION_ROLE || '').trim().toUpperCase() !== 'DISCARD'
    )
    .map(m => {
      const type = String(m.TIPO || '').toUpperCase();
      const kind = type.includes('VÍDEO') || type.includes('VIDEO')
        ? 'video'
        : 'image';

      return {
        media_id: m.ID_MIDIA,
        kind,
        curation_role: m.CURATION_ROLE || '',
        curation_rank: Number(m.CURATION_RANK || 0) || null,
        stage: m.ANALYSIS_STAGE || '',
        shot_type: m.SHOT_TYPE || '',
        visual_summary: m['CONTEÚDO_VISUAL'] || '',
        recommended_use: m.USAR_EM || '',
        best_moment: m.MELHOR_TRECHO || ''
      };
    })
    .sort((a, b) => (a.curation_rank || 999) - (b.curation_rank || 999));

  if (curated.length === 0) reasons.push('NO_NON_DISCARD_CURATED_MEDIA');

  const existingContentCount = contentRows.filter(
    r => String(r.ID_PROJETO || '').trim() === pid
  ).length;

  audit.push({
    project_id: pid,
    storage_status: storage,
    curation_status: curationStatus,
    curation_run_id_present: Boolean(curationRun),
    curated_media_count: curated.length,
    existing_content_count: existingContentCount,
    eligible: reasons.length === 0,
    exclusion_reasons: reasons
  });

  if (reasons.length > 0) continue;

  out.push({
    json: {
      no_work: false,
      project_id: pid,
      curation_run_id: curationRun,
      hero_id: p.CURATION_HERO_ID || '',
      narrative: p.CURATION_NARRATIVE || '',
      carousel_order: String(p.CURATION_CAROUSEL_ORDER || '')
        .split(',')
        .map(x => x.trim())
        .filter(Boolean),
      reel_candidate_ids: String(p.CURATION_REEL_IDS || '')
        .split(',')
        .map(x => x.trim())
        .filter(Boolean),
      media: curated,
      templates: activeTemplates,
      existing_content_count: existingContentCount,
      eligibility_audit: audit,
      context:
        'Planejar conteúdo social sem publicar/agendar. Manter aprovação humana obrigatória antes de qualquer publicação.'
    }
  });
}

if (out.length === 0) {
  return [{
    json: {
      no_work: true,
      status: 'NO_ELIGIBLE_PROJECT',
      message: 'Nenhum projeto passou pelos critérios de planejamento.',
      eligibility_audit: audit,
      checked_at: new Date().toISOString()
    }
  }];
}

return out;

return $input.all().map(i => ({
  json: {
    ...i.json,
    completed: true,
    hint: 'Veja eligibility_audit para saber exatamente por que cada projeto foi excluído.'
  }
}));

return $input.all().map(i => {
  const x = i.json;
  const p = x.plan || {};
  return {
    json: {
      dry_run: true,
      project_id: x.project_id,
      curation_run_id: x.curation_run_id,
      provider: x.provider,
      model: x.model,
      response_id: x.response_id,
      project_strategy: p.project_strategy || '',
      confidence: p.confidence,
      plans: p.plans || [],
      plan_count: Array.isArray(p.plans) ? p.plans.length : 0
    }
  };
});

return $input.all().map(i => {
  const x = i.json;
  return {
    json: {
      ...x,
      route_key: x.no_work === true ? 'NO_WORK' : 'PLAN'
    }
  };
});
